"""Round-2 benchmark note: svg-images-test originals + 769001 figures, before vs after."""
import sys, os, re
ROOT = __file__.rsplit("/benchmark", 1)[0]
sys.path.insert(0, ROOT)
from sciencefig.devonthink import md_figure
from sciencefig.check import hex_to_rgb, check_inline

HERE = os.path.dirname(os.path.abspath(__file__))
after = lambda n: open(os.path.join(HERE, "after", n + ".svg")).read()


def before_svg(n):
    s = open(os.path.join(HERE, "before", n + ".svg")).read()
    s = re.sub(r'id="([^"]+)"', lambda m: f'id="old-{n}-{m.group(1)}"', s)
    s = re.sub(r'url\(#([^)]+)\)', lambda m: f'url(#old-{n}-{m.group(1)})', s)
    s = re.sub(r'href="#([^"]+)"', lambda m: f'href="#old-{n}-{m.group(1)}"', s)
    return hex_to_rgb(s.replace("\n", " "))


def build(jpg_uuids, out):
    md = ["# Figure benchmark – round 2 (hard figures)", "",
          "Harder test figures for the **scientific-figures** skill: six scientific diagrams from the "
          "svg-images-test collection and five figures from the 769001 study guides. Every new figure "
          "passed the automatic layout check (no text collisions, nothing cut off, no clipped curves) "
          "before it was rendered and looked at. New library pieces used here: neuron morphology "
          "(`morph`), real TeX equations inside drawings (`Canvas.math`), network and architecture "
          "blocks (`nets`), phase portraits and stability (`dynamics`), and 3D surfaces (`surf`).",
          "", "---", "", "# Part A – svg-images-test originals", ""]
    A = [
        ("A1. Anatomy of a neuron (morphology)", "labeled_neuron_synapse_diagram", "neuron_labeled",
         "A pyramidal neuron and its parts. Signals flow from the dendrites (apical tuft, apical dendrite, basal dendrites) to the soma and leave along the myelinated axon, which is insulated by myelin sheaths and interrupted by nodes of Ranvier, to the axon terminals. An excitatory synapse (blue triangle) contacts the apical dendrite; an inhibitory synapse (vermilion dot) contacts the soma.",
         ["The dendritic trees are generated by a seeded branching model (`morph.pyramidal`), so they taper naturally and can be redrawn identically.",
          "One neutral colour for the cell; colour is reserved for the synapses, which follow the house convention (excitatory = blue triangle, inhibitory = vermilion dot).",
          "Labels are callouts with leader lines; the linter checks that no label sits on a branch.",
          "Added the nodes of Ranvier and an explicit signal-flow arrow."]),
        ("A2. Cortical layers: feedforward, recurrent and feedback paths", "cortical_layers_feedforward_recurrent_feedback_diagram", "cortical_layers",
         "The canonical cortical circuit. Thalamic input arrives in layer 4, layer 4 cells drive layer 2/3 (feedforward, blue), layer 2/3 cells excite each other and project down to layer 5 (green), and feedback from higher areas lands on the apical tufts in layer 1 (purple, dashed). Layer 5 sends the output to subcortical targets.",
         ["Direct labels on each pathway instead of a colour legend.",
          "Feedback is also dashed, so the three pathways stay distinguishable in grayscale and for colour-blind readers.",
          "Cells are neutral context; only the pathways carry colour. All wiring is computed from the cells' anchor points."]),
        ("A3. Hebbian and anti-Hebbian learning in a linear network", "linear_hebbian_anti_hebbian_network_diagram", "hebbian_net",
         "A linear network that learns principal components. Feedforward weights w (blue) learn by a Hebbian rule with decay (Oja's rule); lateral weights a between outputs (vermilion) learn by an anti-Hebbian rule, which decorrelates the outputs. Each output receives lateral input only from the outputs above it (k < j), so the outputs learn different components in order.",
         ["The equations are typeset as real TeX inside the drawing and coloured like the connections they describe.",
          "Emphasis: the weights into y₁ (the vector w₁) are drawn darker; the rest of the feedforward matrix is light context.",
          "The lateral synapses use the inhibitory terminal (dot) and are labelled with their index rule (k < j)."]),
        ("A4. Spiking responses and the f–I curve", "neuron_fi_curve_spiking_response_diagram", "fi_curve",
         "Responses of a simulated exponential integrate-and-fire neuron to 400 ms current steps. Below the rheobase (about 185 pA) the step only depolarises the cell; above it the neuron fires, and the firing rate grows with the current. The three dots on the f–I curve are the three steps on the left.",
         ["The traces are simulated, not drawn, and the f–I curve comes from the same model, so the panels agree (6 spikes in 400 ms ≈ 16 Hz).",
          "Current strength is encoded by one hue getting darker (an ordered quantity gets a sequential ramp); the dots link each trace to its point on the curve.",
          "Long voltage traces are min/max-decimated (`plot.decimate`): every spike is kept, and the SVG shrank from 2 MB to 22 kB."]),
        ("A5. Autoencoder with a prediction head", "chalkboard_autoencoder_high_dimensional_diagram", "autoencoder",
         "An autoencoder. The encoder E squeezes the high-dimensional input x into a short code h (k ≪ d). From the code, the generator G reconstructs the input and a second decoder D predicts the labels.",
         ["Vectors are drawn as columns of cells, so their lengths show the dimensions; the encoder and decoders are trapezoids that narrow or widen accordingly (`nets.vector`, `nets.funnel`).",
          "The bottleneck code is the one coloured element; input and reconstruction share a colour."]),
        ("A6. Step vs. sigmoid activation and their loss landscapes", "mcculloch_pitts_sigmoid_activation_surfaces", "activation_surfaces",
         "Why gradient learning needs a smooth activation. The loss of a single neuron on a small classification task is plotted over its two weights. With a step activation the landscape is flat plateaus separated by cliffs, so the gradient is zero almost everywhere. With a sigmoid the same landscape becomes smooth slopes that lead down to a minimum.",
         ["The surfaces are the real loss of a seeded toy dataset, not invented shapes.",
          "3D is used only because the shape is the message; the surfaces are lit so the plateaus and slopes read clearly (`surf.View3D`).",
          "The step function uses correct notation (filled dot at x = 0, open dot below)."]),
    ]
    for title, jpg, an, cap, notes in A:
        md += [f"## {title}", "", "**Original**", "", f"![original](x-devonthink-item://{jpg_uuids[jpg]})", "",
               "**Redrawn**", "", md_figure(after(an), cap), "", "**What changed**", ""]
        md += [f"- {n}" for n in notes] + ["", "---", ""]
    md += ["# Part B – figures from the 769001 study guides", "",
           "The same figures, before (as they are in the notes now) and after.", "", "---", ""]
    B = [
        ("B1. Diagonalisation recipe (Tutorial 1)", "Tutorial1_16", "t1_diagonalise",
         "Solving ẋ = Mx through the eigenbasis. The direct route e^(Mt) (top, dashed) is hard because the modes are coupled. The detour is easy: U⁻¹ maps the initial state to mode amplitudes, each amplitude evolves on its own as e^(μₖt), and U maps the result back.",
         ["Before: a five-box chain that ran off the right edge.",
          "After: a commutative diagram, which shows WHY the recipe works: two routes between the same start and end."]),
        ("B2. Phase portrait of a saddle (Tutorial 1)", "Tutorial1_17", "t1_saddle",
         "Phase portrait of ẋ₁ = 3x₁ + 2x₂, ẋ₂ = x₁ − x₂. The origin is a saddle. Along the blue line (u₁, eigenvalue 1 − √6) states decay toward it; along the vermilion line (u₂, eigenvalue 1 + √6) they grow away. The black trajectories start near the blue line: they are first pulled in, then pushed out along u₂.",
         ["Before: hand-drawn trajectories and a legend.",
          "After: the flow field is computed (streamlines), the trajectories are integrated and carry arrows in the direction of time, and the saddle uses the half-filled marker."]),
        ("B3. Trace–determinant plane (Tutorial 1)", "Tutorial1_18", "t1_tracedet",
         "The trace–determinant plane of 2D linear systems. Every region gets a small phase portrait. Only the shaded region (tr < 0 and det > 0) is stable. Above the parabola det = tr²/4 the eigenvalues are complex (spirals), below it real (nodes); below the axis every system is a saddle. The points A–D are the examples from the tutorial.",
         ["Before: labels overlapped each other and the parabola, and one label was cut off.",
          "After: computed mini phase portraits make each region's behaviour visible; every label is lint-checked."]),
        ("B4. Damped E–I oscillation (Tutorial 1)", "Tutorial1_19", "t1_ei_spiral",
         "A damped oscillation of an excitatory–inhibitory pair with eigenvalues (−1 ± 2i)/τ, τ = 10 ms, after a kick to the E neuron. Left: both rates oscillate with a period of about 31 ms inside the decaying envelope e^(−t/τ). Right: the same trajectory in the (r_E, r_I) plane spirals into the stable fixed point.",
         ["Before: the phase-plane panel was cut off at the right edge.",
          "After: E is blue and I is vermilion, as in every circuit figure; the period is measured on the curve; the phase plane uses equal axis scaling."]),
        ("B5. Fixed points of the logistic autapse (Lecture 2)", "Lecture2_13", "l2_fixedpoints",
         "Fixed points of the logistic autapse (θ = 0, β = 20, J = 1) are where g(r + h_ext) crosses the identity line. The strip under each plot shows the flow of r: arrows point the way r moves, filled dots are stable fixed points and the open dot is unstable. At h_ext = −0.5 the network is bistable.",
         ["Added the one-dimensional flow (phase line), so stability is shown, not just stated: filled = stable, open = unstable."]),
    ]
    for title, bn, an, cap, notes in B:
        md += [f"## {title}", "", "**Before**", "", before_svg(bn), "", "**After**", "",
               md_figure(after(an), cap), "", "**What changed**", ""]
        md += [f"- {n}" for n in notes] + ["", "---", ""]
    text = "\n".join(md)
    open(out, "w").write(text)
    nhex = len(re.findall(r"#[0-9a-fA-F]{6}\b", text))
    print(out, len(text), "hex:", nhex)
    return text


if __name__ == "__main__":
    import json
    build(json.loads(sys.argv[1]), sys.argv[2])
